        self.ui
            .widget(cx, ids!(device_setup_banner))
            .set_text(cx, &plain_display_text(&s("this_device")));
        self.ui
            .widget(cx, ids!(device_use_question))
            .set_text(cx, &plain_display_text(&s("device_use_q")));
        self.ui
            .widget(cx, ids!(device_section_label))
